	(15, 15, 'product_cat', '', 0, 0),
	(16, 16, 'product_cat', 'Bàn phím gaming chính hãng từ các thương hiệu lớn, ưu tiên hiệu năng thi đấu, kết nối ổn định và độ hoàn thiện cao.', 0, 24),
	(17, 17, 'product_cat', 'Chuột gaming chính hãng cho FPS, MOBA và MMO, tập trung vào cảm biến chính xác, độ trễ thấp và độ bền ổn định.', 0, 24),
	(18, 18, 'product_cat', 'Tai nghe gaming chính hãng với mic rõ, âm thanh tốt và cảm giác đeo thoải mái cho chơi game lẫn streaming.', 0, 24),
	(19, 19, 'product_cat', 'Webcam, microphone, đèn và phụ kiện streaming phục vụ livestream, thu âm và thiết lập góc quay chuyên nghiệp.', 0, 27),
	(20, 20, 'product_cat', 'Linh kiện PC chính hãng như PSU, RAM, case và tản nhiệt dành cho các bộ máy gaming cần độ ổn định cao.', 0, 30),
	(21, 21, 'product_cat', 'Tay cầm và arcade controller đa nền tảng, phù hợp cho console, PC và game retro hiện đại.', 0, 24),
	(22, 22, 'product_cat', 'Phụ kiện gaming và streaming bổ trợ như mousepad, dock, receiver, boom arm, keycap và các bộ kit mở rộng.', 0, 24),
